/// <summary>
/// PaffH 07.11.25
/// </summary>
[DataContract]
class NDXBVEmailRequestAIDBFieldContract
{
    Common record;
    FieldId fieldId;
    FieldName fieldName;
    TableName tableName;
    str formGroupName;
    str formFieldName;
    Caption caption;
    Types fieldType;

}

Method.Source:
/// <summary>
/// PaffH 08.11.25
/// last modified: PaffH 11.11.25
/// </summary>
/// <param name = "_record">Common</param>
/// <param name = "_fieldId">FieldId</param>
public void initFromFieldId(Common _record, FieldId _fieldId)
{
    record = _record;
    fieldId = _fieldId;
    fieldType = this.getType();
    fieldName = fieldId2Name(record.TableId, fieldId);
    caption = fieldId2PName(record.TableId, fieldId);
    tableName = tableId2Name(_record.TableId);
    formFieldName = 'dyn_' + tableName + '_' + fieldName;
    formGroupName = 'dyn_' + tableName + '_' + fieldName + '_Group';
}

/// <summary>
/// PaffH 07.11.25
/// </summary>
/// <returns>NDXBVEmailRequestAIDBFieldContract</returns>
public static NDXBVEmailRequestAIDBFieldContract construct()
{
    NDXBVEmailRequestAIDBFieldContract contract = new NDXBVEmailRequestAIDBFieldContract();
    return contract;
}

/// <summary>
/// PaffH 07.11.25
/// </summary>
/// <param name = "_record">Common</param>
/// <param name = "_fieldId">FieldId</param>
/// <returns>NDXBVEmailRequestAIDBFieldContract</returns>
public static NDXBVEmailRequestAIDBFieldContract constructFromCommon(Common _record, FieldId _fieldId)
{
    NDXBVEmailRequestAIDBFieldContract contract = new NDXBVEmailRequestAIDBFieldContract();
    contract.initFromFieldId(_record, _fieldId);
    return contract;
}

/// <summary>
/// PaffH 10.11.25
/// last modified: PaffH 25.11.25
/// </summary>
/// <param name = "_formHandler">NDXBVEMailRequestControlCenterAIDBForm</param>
public void populate(NDXBVEMailRequestControlCenterAIDBForm _formHandler)
{
    switch (record.TableId)
    {
        case tableNum(NDXBVEMailRequestHeader) :
            record = _formHandler.parmNDXBVEMailRequestHeader();
            break;
        case tableNum(NDXBVEMailRequestHeaderAIDecisionBasis) :
            record = _formHandler.parmNDXBVEMailRequestHeaderAIDecisionBasis();
            break;
        case tableNum(NDXBVEMailRequestHeaderAIInfo) :
            record = _formHandler.parmNDXBVEMailRequestHeaderAIInfo();
            break;
        case tableNum(NDXBVEMailRequestPlaner) :
            record = _formHandler.parmNDXBVEMailRequestPlaner();
            break;
        case tableNum(NDXBVEMailRequestPlanerAIDecisionBasis) :
            record = _formHandler.parmNDXBVEMailRequestPlanerAIDecisionBasis();
            break;
        case tableNum(NDXBVEMailRequestPlanerAIInfo) :
            record = _formHandler.parmNDXBVEMailRequestPlanerAIInfo();
            break;
        case tableNum(NDXBVEMailRequestInstaller) :
            record = _formHandler.parmNDXBVEMailRequestInstaller();
            break;
        case tableNum(NDXBVEMailRequestInstallerAIDecisionBasis) :
            record = _formHandler.parmNDXBVEMailRequestInstallerAIDecisionBasis();
            break;
        case tableNum(NDXBVEMailRequestInstallerAIInfo) :
            record = _formHandler.parmNDXBVEMailRequestInstallerAIInfo();
            break;
        case tableNum(NDXBVEMailRequestBuildingOwner) :
            record = _formHandler.parmNDXBVEMailRequestBuildingOwner();
            break;
        case tableNum(NDXBVEMailRequestBuildingOwnerAIDecisionBasis) :
            record = _formHandler.parmNDXBVEMailRequestBuildingOwnerAIDecisionBasis();
            break;
        case tableNum(NDXBVEMailRequestBuildingOwnerAIInfo) :
            record = _formHandler.parmNDXBVEMailRequestBuildingOwnerAIInfo();
            break;
        case tableNum(NDXBVEMailRequestADA) :
            record = _formHandler.parmNDXBVEMailRequestADA();
            break;
        case tableNum(NDXBVEMailRequestADAAIDecisionBasis) :
            record = _formHandler.parmNDXBVEMailRequestADAAIDecisionBasis();
            break;
        case tableNum(NDXBVEMailRequestADAAIInfo) :
            record = _formHandler.parmNDXBVEMailRequestADAAIInfo();
            break;
        case tableNum(NDXBVEMailRequestLine) :
            record = _formHandler.parmNDXBVEMailRequestLine();
            break;
        case tableNum(NDXBVEMailRequestLineAIDecisionBasis) :
            record = _formHandler.parmNDXBVEMailRequestLineAIDecisionBasis();
            break;
        case tableNum(NDXBVEMailRequestLineAIInfo) :
            record = _formHandler.parmNDXBVEMailRequestLineAIInfo();
            break;
        case tableNum(Common):
            break;
        default :
            Error(strFmt("@NDXBase:NDXTheElementIsNotTakenIntoAccount", tableId2Name(record.TableId)));
    }
}

/// <summary>
/// PaffH 11.11.25
/// </summary>
/// <returns>FieldType</returns>
private Types getType()
{
    Types retType = Types::void;
    if (!fieldId)
    {
        return retType;
    }
    SysDictField dictField = new SysDictField(record.TableId, fieldId);
    if (!dictField)
    {
        return retType;
    }
    SysDictType dictType = new SysDictType(dictField.typeId());
    if (!dictType)
    {
        return retType;
    }

    return dictType.baseType();
}

/// <summary>
/// PaffH 10.11.25
/// last modified: PaffH 05.12.25
/// </summary>
/// <returns>fieldvalue as string</returns>
public str parmFieldValueAsStr()
{
    str retValue = '';
    if (!fieldId)
    {
        return retValue;
    }
    switch (fieldType)
    {
        case Types::VarString:
        case Types::String:
            retValue = record.(fieldId);
            break;
        case types::Integer:
        case Types::Int64:
            retValue = int2Str(record.(fieldId));
            break;
        case Types::Real:
            retValue = num2Str(record.(fieldId), 16, 2, DecimalSeparator::Comma, ThousandSeparator::Dot);
            break;
        case Types::Date:
            retValue = date2Str(record.(fieldId), 123, 
                DateDay::Digits2,
                DateSeparator::Dot,
                DateMonth::Digits2,
                DateSeparator::Dot,
                DateYear::Digits4);
            break;
        case Types::UtcDateTime:
            retValue = datetime2Str(record.(fieldId));
            break;
        case Types::Enum:
            retValue = enum2Str(record.(fieldId));
            break;
        default:
            Error(strFmt("@NDXBase:NDXTheElementIsNotTakenIntoAccount", fieldType));

    }
    return retValue;
}

